export default function HeroStar() {
    const containerRef = useRef<HTMLDivElement>(null);
    const playPop = useHoverSound("/sound/pop.mp3");

    // Stable ref for the sound so the effect doesn't re-run on every render
    const playSoundRef = useRef(playPop);
    playSoundRef.current = playPop;

    // Track which stars are currently visible so we only fire sound on transitions
    const visibleStars = useRef(new Set<number>());
    // Throttle: timestamp of last pop sound
    const lastPopTime = useRef(0);

    useIsomorphicLayoutEffect(() => {
        const el = containerRef.current;
        if (!el) return;

        const bigStar = el.querySelector<SVGPathElement>("#big-star");
        const svgEl = el.querySelector<SVGSVGElement>("svg");
        const smallStars = el.querySelectorAll<SVGPathElement>(".small-star");

        // Set initial states
        gsap.set(bigStar, { opacity: 0 });
        gsap.set(smallStars, { opacity: 0, scale: 0, transformOrigin: "center center" });

        // Fade in big center star on page load
        gsap.to(bigStar, {
            opacity: 1,
            duration: 2,
            ease: "power2.inOut",
            delay: 0.5,
        });

        // Throttled pop sound helper
        const tryPlayPop = () => {
            const now = Date.now();
            if (now - lastPopTime.current >= 120) {
                lastPopTime.current = now;
                playSoundRef.current();
            }
        };

        // Stars use 0–85% of scroll; last 15% fades out the whole SVG
        const STAR_END = 0.85;

        // Pin the section and pop in small stars on scroll
        const trigger = ScrollTrigger.create({
            trigger: el.parentElement,
            start: "top top",
            end: "+=300%",
            scrub: 1,
            pin: true,
            anticipatePin: 1,
            onUpdate: (self) => {
                const p = self.progress;
                const n = smallStars.length;

                // Map 0–STAR_END to 0–1 for star animations
                const starP = Math.min(p / STAR_END, 1);

                smallStars.forEach((star, i) => {
                    const start = i / n;
                    const end = (i + 1) / n;
                    const local = Math.max(0, Math.min(1, (starP - start) / (end - start)));

                    gsap.set(star, { opacity: local, scale: local });

                    // Sound only on fully appeared / fully disappeared
                    const wasVisible = visibleStars.current.has(i);
                    const isVisible = local >= 1;

                    if (isVisible && !wasVisible) {
                        visibleStars.current.add(i);
                        tryPlayPop();
                    } else if (local <= 0 && wasVisible) {
                        visibleStars.current.delete(i);
                        tryPlayPop();
                    }
                });

                // Last 15%: fade out entire SVG for smooth transition
                if (p > STAR_END) {
                    const fadeP = (p - STAR_END) / (1 - STAR_END); // 0→1
                    gsap.set(svgEl, { opacity: 1 - fadeP });
                } else {
                    gsap.set(svgEl, { opacity: 1 });
                }
            },
        });

        return () => {
            trigger.kill();
        };
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
        <div
            ref={containerRef}
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-20 pointer-events-none"
            style={{ width: "min(80vw, 600px)", height: "min(80vw, 600px)" }}
        >
            <svg
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 208 210"
                fill="none"
                className="w-full h-full"
            >
                <g fill="#fff">
                    {/* Big center star – fades in on load */}
                    <path id="big-star" d={BIG_STAR_D} />
                    {/* Small stars – pop in on scroll with correct shapes */}
                    {STARS.map((s, i) => (
                        <path key={i} className="small-star" d={s.d} />
                    ))}
                </g>
            </svg>
        </div>
    );
}
